let activeFilter = "all";
let selectedId = 1;
const savedSet = new Set();

const listContainer = document.getElementById("indexList");
const inspectorContent = document.getElementById("inspectorContent");
const searchInput = document.getElementById("indexSearch");
const savedCounter = document.getElementById("savedCounter");

/* Кастомный курсор (только для устройств с мышью) */
if (window.matchMedia("(hover: hover)").matches) {
    const dot = document.getElementById("cursorDot");
    const aura = document.getElementById("cursorAura");
    window.addEventListener("mousemove", (e) => {
        dot.style.left = `${e.clientX}px`;
        dot.style.top = `${e.clientY}px`;
        aura.style.left = `${e.clientX}px`;
        aura.style.top = `${e.clientY}px`;
    });
}

/* Рендер списка и правой панели инспектора */
function renderIndex(animate = false) {
    const q = searchInput.value.trim().toLowerCase();
    const filtered = opportunities.filter(item => {
        const byType = activeFilter === "all" || item.type === activeFilter;
        const byQuery = item.title.toLowerCase().includes(q) ||
                        item.company.toLowerCase().includes(q) ||
                        item.tags.some(t => t.toLowerCase().includes(q));
        return byType && byQuery;
    });

    if (filtered.length > 0 && !filtered.some(i => i.id === selectedId)) {
        selectedId = filtered[0].id;
    }

    listContainer.innerHTML = filtered.map((item, i) => `
        <div class="index-row ${item.id === selectedId ? 'active-row' : ''} ${animate ? 'anim' : ''}"
             data-id="${item.id}" ${animate ? `style="--rd: ${Math.min(i, 10) * 45}ms"` : ''}
             onmouseenter="selectItem(${item.id})" onclick="selectItem(${item.id})">
            <span class="row-code">${item.code}</span>
            <div class="row-main">
                <div class="row-company">${item.company}</div>
                <h4>${item.title}</h4>
            </div>
            <span class="row-type">${item.typeLabel}</span>
            <span class="row-pay">${item.compensation}</span>
            <button class="star-btn ${savedSet.has(item.id) ? 'saved' : ''}" onclick="toggleSave(event, ${item.id})">★</button>
        </div>
    `).join("");

    renderInspector(opportunities.find(x => x.id === selectedId) || filtered[0]);
}

function renderInspector(item) {
    if (!item) {
        inspectorContent.innerHTML = `<p class="mono-label">НЕТ ДАННЫХ ПО ЗАПРОСУ</p>`;
        return;
    }
    inspectorContent.innerHTML = `
        <span class="insp-badge">${item.code} // ${item.typeLabel}</span>
        <div class="row-company">${item.company}</div>
        <h3 class="insp-title">${item.title}</h3>
        <p class="insp-desc">${item.description}</p>
        <div class="insp-specs">
            <div>
                <span class="spec-label">ФОРМАТ</span>
                <span class="spec-val">${item.format}</span>
            </div>
            <div>
                <span class="spec-label">ДЛИТЕЛЬНОСТЬ</span>
                <span class="spec-val">${item.duration}</span>
            </div>
            <div>
                <span class="spec-label">ВОЗНАГРАЖДЕНИЕ</span>
                <span class="spec-val">${item.compensation}</span>
            </div>
            <div>
                <span class="spec-label">ДОКУМЕНТЫ ВУЗ</span>
                <span class="spec-val">ЭЦП за 24 часа</span>
            </div>
        </div>
        <div class="insp-tags">
            ${item.tags.map(t => `<span class="insp-tag">${t}</span>`).join("")}
        </div>
        <button class="btn-editorial btn-full" onclick="openDrawer(${item.id})">
            <span>ПОДАТЬ ДОСЬЕ НА ПРОГРАММУ</span>
            <span class="btn-arrow">↗</span>
        </button>
    `;
}

/* Выбор строки: точечное обновление, без перерисовки всего списка */
window.selectItem = function(id) {
    if (selectedId === id) return;
    selectedId = id;
    document.querySelectorAll(".index-row").forEach(row => {
        row.classList.toggle("active-row", +row.dataset.id === id);
    });
    renderInspector(opportunities.find(x => x.id === id));
};

window.toggleSave = function(e, id) {
    e.stopPropagation();
    savedSet.has(id) ? savedSet.delete(id) : savedSet.add(id);
    savedCounter.textContent = savedSet.size;
    const row = e.target.closest(".index-row");
    if (row) row.querySelector(".star-btn").classList.toggle("saved", savedSet.has(id));
};

document.querySelectorAll(".pill").forEach(btn => {
    btn.addEventListener("click", () => {
        document.querySelectorAll(".pill").forEach(b => b.classList.remove("active"));
        btn.classList.add("active");
        activeFilter = btn.dataset.type;
        renderIndex(true);
    });
});

document.querySelectorAll(".triad-col").forEach(col => {
    col.addEventListener("click", () => {
        activeFilter = col.dataset.filter;
        document.querySelectorAll(".pill").forEach(b => {
            b.classList.toggle("active", b.dataset.type === activeFilter);
        });
        document.getElementById("index").scrollIntoView({ behavior: "smooth" });
        renderIndex(true);
    });
});

searchInput.addEventListener("input", () => renderIndex(false));

/* Drawer модальное окно */
const drawer = document.getElementById("applyDrawer");
window.openDrawer = function(id) {
    const item = opportunities.find(x => x.id === id);
    document.getElementById("drawerCode").textContent = `${item.code} // ${item.typeLabel}`;
    document.getElementById("drawerTitle").textContent = item.title;
    document.getElementById("drawerCompany").textContent = `${item.company} • ${item.duration}`;
    drawer.classList.add("open");
};

document.getElementById("closeDrawer").addEventListener("click", () => drawer.classList.remove("open"));
window.addEventListener("keydown", (e) => {
    if (e.key === "Escape") drawer.classList.remove("open");
});

document.querySelector(".editorial-form").addEventListener("submit", (e) => {
    e.preventDefault();
    drawer.classList.remove("open");
    const toast = document.getElementById("statusToast");
    toast.classList.add("show");
    setTimeout(() => toast.classList.remove("show"), 3200);
});

/* Появление секций при скролле */
const revealObserver = new IntersectionObserver(entries => {
    entries.forEach(entry => {
        if (entry.isIntersecting) {
            entry.target.classList.add("in");
            revealObserver.unobserve(entry.target);
        }
    });
}, { threshold: 0.12 });
document.querySelectorAll(".reveal").forEach(el => revealObserver.observe(el));

/* Синхронизация активного пункта дока с секциями */
const dockSections = ["hero", "tracks", "index", "protocol"].map(id => document.getElementById(id));
const dockLinks = [...document.querySelectorAll(".dock-item")];
const dockObserver = new IntersectionObserver(entries => {
    entries.forEach(entry => {
        if (entry.isIntersecting) {
            const idx = dockSections.indexOf(entry.target);
            dockLinks.forEach((link, i) => link.classList.toggle("active", i === idx));
        }
    });
}, { rootMargin: "-42% 0px -42% 0px" });
dockSections.forEach(s => s && dockObserver.observe(s));

