function initPixelAscension() {
    const stage = document.getElementById("artStage");
    const frame = document.getElementById("artFrame");
    const canvas = document.getElementById("ascensionCanvas");
    const img = document.getElementById("heroPhoto");
    const ctx = canvas.getContext("2d");
    const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const canHover = window.matchMedia("(hover: hover)").matches;

    let dpr = 1, W = 0, H = 0;
    let pools = null;
    let particles = [];
    let mouse = { x: 0, y: 0 };
    let parX = 0, parY = 0;
    let last = 0;

    const pick = arr => arr[(Math.random() * arr.length) | 0];

    /* Точный вписанный размер кадра под пропорции фото */
    function fitFrame() {
        if (!img.naturalWidth || !stage) return;
        const cs = getComputedStyle(stage);
        const availW = stage.clientWidth - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight);
        const availH = stage.clientHeight - parseFloat(cs.paddingTop) - parseFloat(cs.paddingBottom);
        if (availW <= 0 || availH <= 0) return;
        const ratio = img.naturalWidth / img.naturalHeight;
        let fw = availW, fh = fw / ratio;
        if (fh > availH) { fh = availH; fw = fh * ratio; }
        frame.style.width = `${Math.floor(fw)}px`;
        frame.style.height = `${Math.floor(fh)}px`;
    }

    function resize() {
        fitFrame();
        const rect = frame.getBoundingClientRect();
        dpr = Math.min(window.devicePixelRatio || 1, 2);
        W = Math.max(1, rect.width);
        H = Math.max(1, rect.height);
        canvas.width = Math.round(W * dpr);
        canvas.height = Math.round(H * dpr);
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        ctx.clearRect(0, 0, W, H);
    }

    /* Пул спавна — предрассчитанный атлас пикселей фотографии (PRKSIS-ATLAS):
       координаты в промилле [x, y, r, g, b, ...]. Цвета приведены к палитре сайта:
       холодные пиксели храма — кобальт → ультрамарин, тёплые пиксели лестницы —
       терракота → янтарь. Работает без сэмплирования canvas, в т.ч. на file:// */
    function buildPools() {
        const top = [], low = [], all = [];
        for (let i = 0; i < PIXEL_ATLAS.length; i += 5) {
            const p = {
                x: PIXEL_ATLAS[i] / 1000,
                y: PIXEL_ATLAS[i + 1] / 1000,
                r: PIXEL_ATLAS[i + 2],
                g: PIXEL_ATLAS[i + 3],
                b: PIXEL_ATLAS[i + 4]
            };
            all.push(p);
            (p.y < 0.56 ? top : low).push(p);
        }
        pools = { top, low, all };
    }

    /* Новая частица: зона спавна взвешена — храм сверху, лестница и портик снизу */
    function spawn(p) {
        let src;
        const roll = Math.random();
        if (roll < 0.62 && pools && pools.top.length) src = pick(pools.top);
        else if (roll < 0.9 && pools && pools.low.length) src = pick(pools.low);
        else src = pools && pools.all.length
            ? pick(pools.all)
            : { x: 0.5 + Math.random() * 0.2, y: 0.45, r: 58, g: 79, b: 232 };

        p.nx = src.x + (Math.random() - 0.5) * 0.02;
        p.ny = src.y + (Math.random() - 0.5) * 0.02;
        p.r = src.r; p.g = src.g; p.b = src.b;
        p.size = (1.2 + Math.random() * 2.2) * Math.max(0.7, W / 520);
        p.vy = 0.1 + Math.random() * 0.17;        /* доля высоты кадра в секунду */
        p.travel = 0.24 + Math.random() * 0.5;    /* дистанция подъёма за жизнь */
        p.ttl = p.travel / p.vy;
        p.t = 0;
        p.amp = 0.0015 + Math.random() * 0.006;
        p.freq = 0.4 + Math.random() * 1.3;
        p.phase = Math.random() * Math.PI * 2;
        p.trail = Math.random() < 0.35;
        p.halo = Math.random() < 0.16;
        p.tw = 2 + Math.random() * 4;
    }

    function drawParticle(p, t) {
        const prog = p.t / p.ttl;
        const fadeIn = Math.min(1, p.t / 0.35);
        const fadeOut = Math.min(1, (1 - prog) / 0.28);
        let a = fadeIn * fadeOut;
        if (a <= 0.01) return;
        a *= 0.72 + 0.28 * Math.sin(t * p.tw + p.phase) ** 2;

        const x = (p.nx + Math.sin(t * p.freq + p.phase) * p.amp + mouse.x * 0.006) * W;
        const y = (p.ny - prog * p.travel) * H;
        const s = p.size;

        if (p.halo) {
            ctx.fillStyle = `rgba(${p.r},${p.g},${p.b},${(a * 0.16).toFixed(3)})`;
            ctx.fillRect(x - s * 2.1, y - s * 2.1, s * 4.2, s * 4.2);
        }
        if (p.trail) {
            const len = s * 3 + p.vy * H * 0.09;
            ctx.strokeStyle = `rgba(${p.r},${p.g},${p.b},${(a * 0.32).toFixed(3)})`;
            ctx.lineWidth = Math.max(0.8, s * 0.42);
            ctx.beginPath();
            ctx.moveTo(x, y + len);
            ctx.lineTo(x, y);
            ctx.stroke();
        }
        ctx.fillStyle = `rgba(${p.r},${p.g},${p.b},${a.toFixed(3)})`;
        ctx.fillRect(x - s / 2, y - s / 2, s, s);
    }

    function drawStatic() {
        ctx.clearRect(0, 0, W, H);
        particles.forEach(p => drawParticle(p, 0));
    }

    function loop(now) {
        const dt = Math.min(0.05, (now - last) / 1000 || 0.016);
        last = now;
        const t = now / 1000;

        ctx.clearRect(0, 0, W, H);

        /* Мягкий параллакс фотографии за курсором */
        const tx = mouse.x * -7, ty = mouse.y * -5;
        parX += (tx - parX) * 0.06;
        parY += (ty - parY) * 0.06;
        img.style.transform = `translate3d(${parX.toFixed(2)}px, ${parY.toFixed(2)}px, 0) scale(1.035)`;

        for (const p of particles) {
            p.t += dt;
            if (p.t >= p.ttl) { spawn(p); continue; }
            drawParticle(p, t);
        }
        requestAnimationFrame(loop);
    }

    function start() {
        resize();
        buildPools();
        const count = Math.max(110, Math.min(240, Math.round(W * H / 2200)));
        particles = Array.from({ length: count }, () => {
            const p = {};
            spawn(p);
            p.t = Math.random() * p.ttl * 0.85;  /* рассинхронизированный старт */
            return p;
        });
        if (reduceMotion) {
            particles.forEach(p => { p.t = p.ttl * (0.15 + Math.random() * 0.55); });
            drawStatic();
        } else {
            requestAnimationFrame(loop);
        }
    }

    window.addEventListener("resize", resize);
    if (window.ResizeObserver) {
        new ResizeObserver(resize).observe(stage);
    }
    if (canHover) {
        stage.addEventListener("mousemove", (e) => {
            const rect = stage.getBoundingClientRect();
            mouse.x = ((e.clientX - rect.left) / rect.width - 0.5) * 2;
            mouse.y = ((e.clientY - rect.top) / rect.height - 0.5) * 2;
        });
        stage.addEventListener("mouseleave", () => { mouse.x = 0; mouse.y = 0; });
    }

    if (img.complete && img.naturalWidth) {
        start();
    } else {
        img.addEventListener("load", start, { once: true });
        img.addEventListener("error", () => { resize(); }, { once: true });
    }
}

renderIndex(true);
initPixelAscension();
